mapper.sql:
SELECT c.id, c.course_code, c.course_name, c.credit, c.hours, c.course_type, c.semester_id, se.semester_name, c.teacher_id, t.name AS teacher_name, c.status, c.score_status, c.submit_time FROM course c JOIN semester se ON c.semester_id = se.id JOIN teacher t ON c.teacher_id = t.id
AND (c.course_code LIKE CONCAT('%', #{keyword}, '%') OR c.course_name LIKE CONCAT('%', #{keyword}, '%'))
AND c.semester_id = #{semesterId}
AND c.teacher_id = #{teacherId}
ORDER BY se.start_date DESC, c.course_code

mapper.select:
SELECT c.id, c.course_code, c.course_name, c.credit, c.hours, c.course_type, c.semester_id, se.semester_name, c.teacher_id, t.name AS teacher_name, c.status, c.score_status, c.submit_time FROM course_student cs JOIN course c ON cs.course_id = c.id JOIN semester se ON c.semester_id = se.id JOIN teacher t ON c.teacher_id = t.id WHERE cs.student_id = #{studentId}
AND c.semester_id = #{semesterId}
ORDER BY se.start_date DESC, c.course_code
